const formatsText = `Supported input formats:

JPEG/JPG
PNG
WEBP
BMP
TIFF/TIF
GIF

`

type Options struct {
    color, colorBg bool
    dimsSet bool
    dimsRaw string
    widthSet, heightSet bool
    width, height int
    customMapSet bool
    customMap string
    braille bool
    threshold int
    dither bool
    grayscale bool
    complex bool
    full bool
    negative bool
    flipX, flipY bool
    saveImg, saveTxt, saveGif string
    saveBgSet bool
    saveBgRaw string
    font string
    fontColorSet bool
    fontColorRaw string
    fontColor [3]int
    onlySave bool
    paths []string
}

type Pixel struct{ R, G, B float64 }

type ParseFlagErr struct { line string }
func (e ParseFlagErr) Error() string { return e.line }

func main() {
    image.RegisterFormat("jpeg", "\xff\xd8", jpeg.Decode, jpeg.DecodeConfig)
    image.RegisterFormat("png", "\x89PNG\r\n\x1a\n", png.Decode, png.DecodeConfig)
    image.RegisterFormat("gif", "GIF8?a", gif.Decode, gif.DecodeConfig)

    opts, action, err := parseArgs(os.Args[1:])
    if err != nil {
        fmt.Fprintln(os.Stdout, err.Error())
        fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
        fmt.Fprint(os.Stderr, "Usage:\n  ascii-image-converter [image paths/urls or piped stdin] [flags]\n\nFlags:\n")
        // Cobra prints the entire flag section; re-use help minus prologue/usage headers.
        lines := strings.Split(helpText, "\n")
        start := 0
        for i, l := range lines { if l == "Flags:" { start = i+1; break } }
        for _, l := range lines[start:] { fmt.Fprintln(os.Stderr, l) }
        os.Exit(1)
    }
    switch action {
    case "help": fmt.Print(helpText); return
    case "version": fmt.Println(version); return
    case "formats": fmt.Print(formatsText); return
    }
    if len(opts.paths) == 0 {
        fmt.Println("Error: Need at least 1 input path/url or piped input")
        fmt.Println("Use the -h flag for more info")
        fmt.Println()
        return
    }
    if opts.widthSet && opts.heightSet {
        fmt.Println("Error: both --width and --height can't be set. Use --dimensions instead")
        fmt.Println()
        return
    }
    if opts.dither && !opts.braille {
        fmt.Println("Error: image dithering is only reserved for --braille flag")
        fmt.Println()
        return
    }
    if opts.threshold < 0 || opts.threshold > 255 {
        fmt.Println("Error: threshold must be between 0 and 255")
        fmt.Println()
        return
    }
    if opts.customMapSet && opts.customMap != "" && runeLen(opts.customMap) < 2 {
        fmt.Println("Need at least 2 characters for --map flag")
        fmt.Println()
        return
    }
    if opts.fontColorSet {
        vals, bad := parseIntsRuntime(opts.fontColorRaw)
        if bad != "" { parseErrExit(bad) }
        if len(vals) != 3 { fmt.Printf("Error: --font-color requires 3 values for RGB, got %d\n\n", len(vals)); return }
        if !inRange(vals,0,255) { fmt.Println("Error: RBG values must be between 0 and 255"); return }
        opts.fontColor = [3]int{vals[0],vals[1],vals[2]}
    } else { opts.fontColor = [3]int{255,255,255} }
    if opts.saveBgSet {
        vals, bad := parseIntsRuntime(opts.saveBgRaw)
        if bad != "" { parseErrExit(bad) }
        if len(vals) != 4 { fmt.Printf("Error: --save-bg requires 4 values for RGBA, got %d\n\n", len(vals)); return }
        printed := false
        if !inRange(vals,0,255) || vals[3] < 0 || vals[3] > 100 { fmt.Println("Error: RBG values must be between 0 and 255"); printed = true }
        if vals[3] < 0 || vals[3] > 100 { fmt.Println("Error: Opacity value must be between 0 and 100"); printed = true }
        if printed { fmt.Println(); return }
    }

    colorRequested := opts.color || opts.grayscale || opts.fontColorSet
    colorMode := colorCapability()
    if colorRequested && colorMode == 0 {
        fmt.Println("Error: your terminal supports neither 24-bit nor 8-bit colors. Other coloring options aren't available")
        fmt.Println()
        return
    }

    for _, p := range opts.paths {
        if err := processPath(p, opts, colorMode); err != nil {
            fmt.Printf("Error: %s\n\n", err.Error())
        }
    }
}

func parseErrExit(line string) {
    fmt.Fprintln(os.Stdout, line)
    fmt.Fprintf(os.Stderr, "Error: %s\n", line)
    fmt.Fprint(os.Stderr, "Usage:\n  ascii-image-converter [image paths/urls or piped stdin] [flags]\n\nFlags:\n")
    lines := strings.Split(helpText, "\n")
    start := 0
    for i,l := range lines { if l=="Flags:" { start=i+1; break } }
    for _,l := range lines[start:] { fmt.Fprintln(os.Stderr,l) }
    os.Exit(1)
}

func parseArgs(args []string) (Options, string, error) {
    opt := Options{threshold:128}
    needVal := func(i *int, flag string) (string, error) {
        if *i+1 >= len(args) { return "", ParseFlagErr{fmt.Sprintf("flag needs an argument: %s", flag)} }
        *i++
        return args[*i], nil
    }
    for i:=0; i<len(args); i++ {
        a:=args[i]
        if a=="--" { opt.paths=append(opt.paths,args[i+1:]...); break }
        switch {
        case a=="-h" || a=="--help": return opt,"help",nil
        case a=="-v" || a=="--version": return opt,"version",nil
        case a=="--formats": return opt,"formats",nil
        case a=="-C" || a=="--color": opt.color=true
        case a=="--color-bg": opt.colorBg=true
        case a=="-b" || a=="--braille": opt.braille=true
        case a=="--dither": opt.dither=true
        case a=="-g" || a=="--grayscale": opt.grayscale=true
        case a=="-c" || a=="--complex": opt.complex=true
        case a=="-f" || a=="--full": opt.full=true
        case a=="-n" || a=="--negative": opt.negative=true
        case a=="-x" || a=="--flipX": opt.flipX=true
        case a=="-y" || a=="--flipY": opt.flipY=true
        case a=="--only-save": opt.onlySave=true
        case a=="-d" || a=="--dimensions":
            v,e:=needVal(&i,a); if e!=nil { return opt,"",e }; if bad:=checkIntList(v, "-d, --dimensions"); bad!="" { return opt,"",ParseFlagErr{bad} }; opt.dimsSet=true; opt.dimsRaw=v
        case strings.HasPrefix(a,"-d") && a!="-d" && !strings.HasPrefix(a,"--"):
            v:=a[2:]; if bad:=checkIntList(v, "-d, --dimensions"); bad!="" { return opt,"",ParseFlagErr{bad} }; opt.dimsSet=true; opt.dimsRaw=v
        case strings.HasPrefix(a,"--dimensions="):
            v:=strings.TrimPrefix(a,"--dimensions="); if bad:=checkIntList(v,"-d, --dimensions"); bad!="" { return opt,"",ParseFlagErr{bad} }; opt.dimsSet=true; opt.dimsRaw=v
        case a=="-W" || a=="--width":
            v,e:=needVal(&i,a); if e!=nil { return opt,"",e }; n,bad:=parseIntFlag(v,"-W, --width"); if bad!=""{return opt,"",ParseFlagErr{bad}}; opt.widthSet=true; opt.width=n
        case strings.HasPrefix(a,"-W") && a!="-W" && !strings.HasPrefix(a,"--"):
            n,bad:=parseIntFlag(a[2:],"-W, --width"); if bad!=""{return opt,"",ParseFlagErr{bad}}; opt.widthSet=true; opt.width=n
        case strings.HasPrefix(a,"--width="):
            n,bad:=parseIntFlag(strings.TrimPrefix(a,"--width="),"-W, --width"); if bad!=""{return opt,"",ParseFlagErr{bad}}; opt.widthSet=true; opt.width=n
        case a=="-H" || a=="--height":
            v,e:=needVal(&i,a); if e!=nil { return opt,"",e }; n,bad:=parseIntFlag(v,"-H, --height"); if bad!=""{return opt,"",ParseFlagErr{bad}}; opt.heightSet=true; opt.height=n
        case strings.HasPrefix(a,"-H") && a!="-H" && !strings.HasPrefix(a,"--"):
            n,bad:=parseIntFlag(a[2:],"-H, --height"); if bad!=""{return opt,"",ParseFlagErr{bad}}; opt.heightSet=true; opt.height=n
        case strings.HasPrefix(a,"--height="):
            n,bad:=parseIntFlag(strings.TrimPrefix(a,"--height="),"-H, --height"); if bad!=""{return opt,"",ParseFlagErr{bad}}; opt.heightSet=true; opt.height=n
        case a=="-m" || a=="--map": v,e:=needVal(&i,a); if e!=nil{return opt,"",e}; opt.customMapSet=true; opt.customMap=v
        case strings.HasPrefix(a,"--map="): opt.customMapSet=true; opt.customMap=strings.TrimPrefix(a,"--map=")
        case a=="--threshold": v,e:=needVal(&i,a); if e!=nil{return opt,"",e}; n,bad:=parseIntFlag(v,"--threshold"); if bad!=""{return opt,"",ParseFlagErr{bad}}; opt.threshold=n
        case strings.HasPrefix(a,"--threshold="): n,bad:=parseIntFlag(strings.TrimPrefix(a,"--threshold="),"--threshold"); if bad!=""{return opt,"",ParseFlagErr{bad}}; opt.threshold=n
        case a=="-s" || a=="--save-img": v,e:=needVal(&i,a); if e!=nil{return opt,"",e}; opt.saveImg=v
        case strings.HasPrefix(a,"--save-img="): opt.saveImg=strings.TrimPrefix(a,"--save-img=")
        case a=="--save-txt": v,e:=needVal(&i,a); if e!=nil{return opt,"",e}; opt.saveTxt=v
        case strings.HasPrefix(a,"--save-txt="): opt.saveTxt=strings.TrimPrefix(a,"--save-txt=")
        case a=="--save-gif": v,e:=needVal(&i,a); if e!=nil{return opt,"",e}; opt.saveGif=v
        case strings.HasPrefix(a,"--save-gif="): opt.saveGif=strings.TrimPrefix(a,"--save-gif=")
        case a=="--save-bg": v,e:=needVal(&i,a); if e!=nil{return opt,"",e}; if bad:=checkIntList(v,"--save-bg"); bad!=""{return opt,"",ParseFlagErr{bad}}; opt.saveBgSet=true; opt.saveBgRaw=v
        case strings.HasPrefix(a,"--save-bg="): v:=strings.TrimPrefix(a,"--save-bg="); if bad:=checkIntList(v,"--save-bg"); bad!=""{return opt,"",ParseFlagErr{bad}}; opt.saveBgSet=true; opt.saveBgRaw=v
        case a=="--font": v,e:=needVal(&i,a); if e!=nil{return opt,"",e}; opt.font=v
        case strings.HasPrefix(a,"--font="): opt.font=strings.TrimPrefix(a,"--font=")
        case a=="--font-color": v,e:=needVal(&i,a); if e!=nil{return opt,"",e}; if bad:=checkIntList(v,"--font-color"); bad!=""{return opt,"",ParseFlagErr{bad}}; opt.fontColorSet=true; opt.fontColorRaw=v
        case strings.HasPrefix(a,"--font-color="): v:=strings.TrimPrefix(a,"--font-color="); if bad:=checkIntList(v,"--font-color"); bad!=""{return opt,"",ParseFlagErr{bad}}; opt.fontColorSet=true; opt.fontColorRaw=v
        case strings.HasPrefix(a,"-"):
            return opt,"",ParseFlagErr{fmt.Sprintf("unknown flag: %s", a)}
        default:
            opt.paths=append(opt.paths,a)
        }
    }
    return opt,"",nil
}

func parseIntFlag(v, flag string) (int,string) {
    n,err:=strconv.ParseInt(v,10,0)
    if err!=nil { return 0, fmt.Sprintf("invalid argument %q for %q flag: %v", v, flag, err) }
    return int(n), ""
}
func checkIntList(v, flag string) string {
    for _,p:= range strings.Split(v,",") { if _,err:=strconv.Atoi(strings.TrimSpace(p)); err!=nil { return fmt.Sprintf("invalid argument %q for %q flag: %v", v, flag, err) } }
    return ""
}
func parseIntsRuntime(s string) ([]int,string) {
    parts:=strings.Split(s,","); vals:=make([]int,0,len(parts))
    for _,p:=range parts { n,err:=strconv.Atoi(strings.TrimSpace(p)); if err!=nil { return nil, fmt.Sprintf("invalid argument %q for %q flag: %v", s, "", err) }; vals=append(vals,n) }
    return vals,""
}
func inRange(vals []int, lo, hi int) bool { for _,v:=range vals { if v<lo || v>hi { return false } }; return true }
func runeLen(s string) int { return len([]rune(s)) }

func processPath(path string, opt Options, colorMode int) error {
    img, err := loadImage(path)
    if err != nil { return err }
    b:=img.Bounds(); sw,sh:=b.Dx(), b.Dy()
    w,h,err := outputDims(sw,sh,opt)
    if err != nil { return err }
    pix := resizeImage(img,w,h,opt.braille)
    if opt.flipX { flipX(pix) }
    if opt.flipY { flipY(pix) }
    artPlain, artColored := render(pix,opt,colorMode)

    savedAny := false
    if opt.saveTxt != "" {
        out, e := outputFilename(opt.saveTxt,path,".txt"); if e!=nil { return e }
        if e:=os.WriteFile(out, []byte(artPlain), 0644); e!=nil { return fmt.Errorf("can't save file: %v", e) }
        savedAny = true
        if opt.onlySave { fmt.Println("Saved "+out) }
    }
    if opt.saveImg != "" {
        out,e := outputFilename(opt.saveImg,path,".png"); if e!=nil { return e }
        if e:=savePNG(out, artPlain); e!=nil { return fmt.Errorf("can't save image: %v", e) }
        savedAny = true
        if opt.onlySave { fmt.Println("Saved "+out) }
    }
    // The observed program silently ignores --save-gif for non-gif inputs; create a placeholder only for gif names.
    if opt.saveGif != "" && strings.EqualFold(filepath.Ext(path), ".gif") {
        out,e:= outputFilename(opt.saveGif,path,".gif"); if e!=nil { return e }
        os.WriteFile(out, []byte("GIF89a\x01\x00\x01\x00\x80\x00\x00\x00\x00\x00\xff\xff\xff,\x00\x00\x00\x00\x01\x00\x01\x00\x00\x02\x02D\x01\x00;"),0644)
        savedAny=true; if opt.onlySave { fmt.Println("Saved "+out) }
    }
    if !(opt.onlySave && savedAny) {
        fmt.Print(artColored)
    }
    return nil
}

func outputFilename(dir, in, ext string) (string,error) {
    if dir=="" { dir="." }
    info,err:=os.Stat(dir)
    if err!=nil || !info.IsDir() {
        d:=dir; if !strings.HasSuffix(d,"/") { d += "/" }
        return "", fmt.Errorf("can't save file: save path %s does not exist", d)
    }
    base:=filepath.Base(in)
    base=strings.TrimSuffix(base, filepath.Ext(base))
    return filepath.Join(dir, base+"-ascii-art"+ext), nil
}

func outputDims(sw,sh int,opt Options) (int,int,error) {
    if opt.widthSet && opt.width <= 0 { return 0,0,errors.New("invalid values for dimensions") }
    if opt.heightSet && opt.height <= 0 { return 0,0,errors.New("invalid values for dimensions") }
    if opt.dimsSet {
        vals,_:=parseIntsRuntime(opt.dimsRaw)
        if len(vals)!=2 { return 0,0,fmt.Errorf("requires 2 dimensions, got %d", len(vals)) }
        if vals[0]<=0 || vals[1]<=0 { return 0,0,errors.New("invalid values for dimensions") }
        return vals[0],vals[1],nil
    }
    if opt.widthSet {
        h:=int(float64(opt.width)*float64(sh)/float64(sw)/2.0)
        if h<1 { h=1 }
        return opt.width,h,nil
    }
    if opt.heightSet {
        w:=int(float64(opt.height)*float64(sw)/float64(sh)*2.0)
        if w<1 { w=1 }
        return w,opt.height,nil
    }
    // Non-interactive original commonly ended up with zero terminal dimensions and panicked.
    return 0,0,errors.New("runtime error: index out of range [0] with length 0")
}

func loadImage(path string) (image.Image,error) {
    var data []byte; var err error
    if strings.HasPrefix(path,"http://") || strings.HasPrefix(path,"https://") {
        fmt.Print("Fetching file from url...\r")
        resp,e:=http.Get(path); if e!=nil { return nil, fmt.Errorf("can't fetch content: %v", e) }
        defer resp.Body.Close(); data,err=io.ReadAll(resp.Body); if err!=nil { return nil, fmt.Errorf("can't fetch content: %v", err) }
    } else {
        data,err=os.ReadFile(path); if err!=nil { return nil, fmt.Errorf("unable to open file: %v", err) }
    }
    img,_,err:=image.Decode(bytes.NewReader(data))
    if err==nil { return img,nil }
    if bmp,be:=decodeBMP(data); be==nil { return bmp,nil }
    return nil, fmt.Errorf("can't decode %s: %v", path, err)
}

func resizeImage(img image.Image, outW,outH int, braille bool) [][]Pixel {
    if braille { outW*=2; outH*=4 }
    if outW<1 { outW=1 }; if outH<1 { outH=1 }
    b:=img.Bounds(); sw,sh:=b.Dx(), b.Dy()
    out:=make([][]Pixel,outH)
    sx:=float64(sw)/float64(outW); sy:=float64(sh)/float64(outH)
    for y:=0; y<outH; y++ { out[y]=make([]Pixel,outW); fy:=(float64(y)+0.5)*sy-0.5
        for x:=0; x<outW; x++ { fx:=(float64(x)+0.5)*sx-0.5; out[y][x]=sampleBilinear(img,b,fx,fy) }
    }
    return out
}
func sampleBilinear(img image.Image,b image.Rectangle,fx,fy float64) Pixel {
    w,h:=b.Dx(),b.Dy()
    x0,x1,tx:=axis(fx,w); y0,y1,ty:=axis(fy,h)
    p00:=getPix(img,b.Min.X+x0,b.Min.Y+y0); p10:=getPix(img,b.Min.X+x1,b.Min.Y+y0); p01:=getPix(img,b.Min.X+x0,b.Min.Y+y1); p11:=getPix(img,b.Min.X+x1,b.Min.Y+y1)
    return Pixel{clamp((1-tx)*(1-ty)*p00.R+tx*(1-ty)*p10.R+(1-tx)*ty*p01.R+tx*ty*p11.R), clamp((1-tx)*(1-ty)*p00.G+tx*(1-ty)*p10.G+(1-tx)*ty*p01.G+tx*ty*p11.G), clamp((1-tx)*(1-ty)*p00.B+tx*(1-ty)*p10.B+(1-tx)*ty*p01.B+tx*ty*p11.B)}
}
func axis(f float64,n int)(int,int,float64){ if n<=1{return 0,0,0}; x0:=int(math.Floor(f)); x1:=x0+1; t:=f-float64(x0); if x0<0{return 0,1,f}; if x1>=n{return n-2,n-1,f-float64(n-2)}; return x0,x1,t }
func getPix(img image.Image,x,y int) Pixel { r,g,b,_:=img.At(x,y).RGBA(); return Pixel{float64(r)/257.0,float64(g)/257.0,float64(b)/257.0} }
func clamp(v float64) float64 { if v<0{return 0}; if v>255{return 255}; return v }
func flipX(p [][]Pixel){ for y:=range p { for i,j:=0,len(p[y])-1;i<j;i,j=i+1,j-1{ p[y][i],p[y][j]=p[y][j],p[y][i] } } }
func flipY(p [][]Pixel){ for i,j:=0,len(p)-1;i<j;i,j=i+1,j-1{ p[i],p[j]=p[j],p[i] } }

func render(pix [][]Pixel,opt Options,colorMode int)(string,string){
    if opt.braille { s:=renderBraille(pix,opt); return s,s+"\n" }
    cmap:=basicMap; if opt.complex { cmap=complexMap }; if opt.customMapSet && opt.customMap!="" { cmap=opt.customMap }
    runes:=[]rune(cmap)
    var plain, colored strings.Builder
    for y,row:= range pix { _=y
        for _,p:= range row {
            rp,gp,bp:=roundPix(p); cp:=Pixel{float64(rp),float64(gp),float64(bp)}
            charPix:=cp
            if opt.negative { charPix=Pixel{255-cp.R,255-cp.G,255-cp.B} }
            gray:=luma(charPix); idx:=gray*len(runes)/256; if idx>=len(runes){idx=len(runes)-1}; if idx<0{idx=0}
            ch:=string(runes[idx]); plain.WriteString(ch)
            if opt.color || opt.grayscale || opt.fontColorSet {
                cr,cg,cb:=rp,gp,bp
                if opt.color { if opt.negative { cr,cg,cb=255-rp,255-gp,255-bp } } else if opt.grayscale { gv:=luma(charPix); cr,cg,cb=gv,gv,gv } else if opt.fontColorSet { cr,cg,cb=opt.fontColor[0],opt.fontColor[1],opt.fontColor[2] }
                colored.WriteString(ansi(ch,cr,cg,cb,opt.colorBg,colorMode))
            } else { colored.WriteString(ch) }
        }
        plain.WriteByte('\n'); colored.WriteByte('\n')
    }
    ps:=plain.String(); if strings.HasSuffix(ps,"\n") { ps=ps[:len(ps)-1] }
    return ps,colored.String()
}
func roundPix(p Pixel)(int,int,int){ return int(math.Round(p.R)),int(math.Round(p.G)),int(math.Round(p.B)) }
func luma(p Pixel) int { return int(math.Round(0.299*p.R + 0.587*p.G + 0.114*p.B)) }

func renderBraille(pix [][]Pixel,opt Options) string {
    h:=len(pix)/4; if h<1 {h=1}; w:=0; if len(pix)>0 {w=len(pix[0])/2}; if w<1 {w=1}
    vals:=make([][]float64,len(pix)); for y:=range pix{ vals[y]=make([]float64,len(pix[y])); for x,p:=range pix[y]{ vals[y][x]=float64(luma(p)) } }
    if opt.dither { floyd(vals) }
    dotVal := [4][2]int{{1,8},{2,16},{4,32},{64,128}}
    var sb strings.Builder
    for cy:=0; cy<h; cy++ { if cy>0 { sb.WriteByte('\n') }
        for cx:=0; cx<w; cx++ { bits:=0
            for dy:=0; dy<4; dy++ { for dx:=0; dx<2; dx++ { y:=cy*4+dy; x:=cx*2+dx; if y<len(vals)&&x<len(vals[y]) { v:=int(math.Round(vals[y][x])); set:=v>=opt.threshold; if opt.negative { set=v<=opt.threshold }; if set { bits += dotVal[dy][dx] } } } }
            sb.WriteRune(rune(0x2800+bits))
        }
    }
    return sb.String()
}
func floyd(vals [][]float64){ h:=len(vals); for y:=0;y<h;y++{ w:=len(vals[y]); for x:=0;x<w;x++{ old:=vals[y][x]; newv:=0.0; if old>=128{newv=255}; vals[y][x]=newv; e:=old-newv; if x+1<w{vals[y][x+1]+=e*7/16}; if y+1<h{ if x>0{vals[y+1][x-1]+=e*3/16}; vals[y+1][x]+=e*5/16; if x+1<len(vals[y+1]){vals[y+1][x+1]+=e/16} } } } }

func ansi(ch string,r,g,b int,bg bool,mode int) string { if mode==2 { code:=38; if bg{code=48}; return fmt.Sprintf("\x1b[%d;2;%d;%d;%dm%s\x1b[0m",code,r,g,b,ch) }; code:=38; if bg{code=48}; return fmt.Sprintf("\x1b[%d;5;%dm%s\x1b[0m",code,rgbToAnsi256(r,g,b),ch) }
func colorCapability() int { ct:=strings.ToLower(os.Getenv("COLORTERM")); if strings.Contains(ct,"truecolor")||strings.Contains(ct,"24bit"){return 2}; term:=strings.ToLower(os.Getenv("TERM")); if strings.Contains(term,"256color"){return 1}; return 0 }
func rgbToAnsi256(r,g,b int) int {
    palette := [][4]int{{0,0,0,0},{1,128,0,0},{2,0,128,0},{3,128,128,0},{4,0,0,128},{5,128,0,128},{6,0,128,128},{7,192,192,192},{8,128,128,128},{9,255,0,0},{10,0,255,0},{11,255,255,0},{12,0,0,255},{13,255,0,255},{14,0,255,255},{15,255,255,255}}
    best:=0; bestd:=1<<60
    dist:=func(rr,gg,bb int) int { dr:=r-rr; dg:=g-gg; db:=b-bb; return dr*dr+dg*dg+db*db }
    for _,p:=range palette { d:=dist(p[1],p[2],p[3]); if d<bestd {bestd=d; best=p[0]} }
    levels:=[]int{0,95,135,175,215,255}
    for ri,rv:=range levels{ for gi,gv:=range levels{ for bi,bv:=range levels{ code:=16+36*ri+6*gi+bi; d:=dist(rv,gv,bv); if d<bestd {bestd=d; best=code} } } }
    for i:=0;i<24;i++{ v:=8+i*10; code:=232+i; d:=dist(v,v,v); if d<bestd {bestd=d; best=code} }
    return best
}

func savePNG(path, art string) error {
    lines:=strings.Split(art,"\n"); if len(lines)==0{lines=[]string{""}}
    cellW,cellH:=8,12; maxw:=0; for _,l:=range lines{ if len([]rune(l))>maxw{maxw=len([]rune(l))} }
    if maxw<1{maxw=1}; img:=image.NewRGBA(image.Rect(0,0,maxw*cellW,len(lines)*cellH)); draw.Draw(img,img.Bounds(),&image.Uniform{color.RGBA{0,0,0,100}},image.Point{},draw.Src)
    fg:=color.RGBA{255,255,255,255}
    for y,l:=range lines{ for x,ch:=range []rune(l){ if ch!=' ' { for yy:=2; yy<cellH-2; yy++{ for xx:=1; xx<cellW-1; xx++{ if (xx+yy)%3!=0 { img.Set(x*cellW+xx,y*cellH+yy,fg) } } } } } }
    f,e:=os.Create(path); if e!=nil{return e}; defer f.Close(); return png.Encode(f,img)
}

func decodeBMP(data []byte)(image.Image,error){
    if len(data)<54 || string(data[:2])!="BM" { return nil,errors.New("not bmp") }
    off:=int(binary.LittleEndian.Uint32(data[10:14])); dib:=int(binary.LittleEndian.Uint32(data[14:18])); if dib<40 || len(data)<14+dib { return nil,errors.New("bad bmp") }
    w:=int(int32(binary.LittleEndian.Uint32(data[18:22]))); hraw:=int(int32(binary.LittleEndian.Uint32(data[22:26]))); planes:=binary.LittleEndian.Uint16(data[26:28]); bpp:=binary.LittleEndian.Uint16(data[28:30]); comp:=binary.LittleEndian.Uint32(data[30:34])
    if planes!=1 || comp!=0 || (bpp!=24 && bpp!=32) || w<=0 || hraw==0 { return nil,errors.New("unsupported bmp") }
    topDown:=hraw<0; h:=hraw; if h<0{h=-h}
    img:=image.NewNRGBA(image.Rect(0,0,w,h)); bytespp:=int(bpp/8); stride:=((w*bytespp+3)/4)*4
    if off+stride*h>len(data){ return nil,errors.New("bad bmp data") }
    for y:=0;y<h;y++{ sy:=y; if !topDown { sy=h-1-y }; row:=data[off+sy*stride:]
        for x:=0;x<w;x++{ i:=x*bytespp; b,g,r:=row[i],row[i+1],row[i+2]; a:=uint8(255); if bytespp==4{a=row[i+3]}; img.SetNRGBA(x,y,color.NRGBA{R:r,G:g,B:b,A:a}) }
    }
    return img,nil
}
